"""FreeMarker usage per component (macros from freemarker/ui.ftl). The HTML tab shows each demo's own markup."""
IMP = '[#import "/ui/ui.ftl" as ui]\n'
FTL = {
"accordion": '[@ui.accordion default="a" items=[\n  {"value":"a", "title":"რა არის Despani?", "content":"<p>პორტალი.</p>"},\n  {"value":"b", "title":"Colibri UI?", "content":"<p>Headless UI.</p>"}\n]/]',
"alert": '[@ui.alert role="status"]<strong>ინფორმაცია:</strong> ცვლილებები შენახულია.[/@ui.alert]\n[@ui.alert role="alert" variant="destructive"]ვერ მოხერხდა.[/@ui.alert]',
"alert-dialog": '[@ui.dialog kind="alert-dialog" trigger="სტატიის წაშლა…" title="დარწმუნებული ხართ?"\n           description="ამ მოქმედების გაუქმება შეუძლებელია."]\n  [@ui.close returnValue="cancel" autofocus=true]გაუქმება[/@ui.close]\n  [@ui.close returnValue="ok" variant="destructive"]წაშლა[/@ui.close]\n[/@ui.dialog]',
"aspect-ratio": '[@ui.c ui="aspect-ratio" attrs={"style":"aspect-ratio:16/9"}]<img src="${cover}" alt="">[/@ui.c]',
"avatar": '[@ui.avatar src=user.avatarUrl! alt=user.name fallback="LD"/]',
"badge": '[@ui.badge]Default[/@ui.badge]\n[@ui.badge variant="secondary"]Secondary[/@ui.badge]\n[@ui.badge variant="outline" removable=true]ტეგი[/@ui.badge]',
"button": '[@ui.button]Save[/@ui.button]\n[@ui.button variant="outline"]Cancel[/@ui.button]\n[@ui.button variant="destructive"]წაშლა[/@ui.button]\n[@ui.button type="submit" loading=saving]Submit[/@ui.button]',
"spinner": '[@ui.spinner /]\n[@ui.spinner size="lg" variant="dots" label="Loading messages…" /]\n[@ui.button disabled=true][@ui.spinner size="sm" label="Saving…" /] Saving…[/@ui.button]',
"button-group": '[@ui.buttonGroup label="Text align" type="single" value="center" name="align" required=true]\n  <button data-value="left">Left</button><button data-value="center">Center</button><button data-value="right">Right</button>\n[/@ui.buttonGroup]',
"card": '[@ui.card title=article.title description=article.date]\n  ${article.intro}\n[/@ui.card]',
"carousel": '[@ui.c ui="carousel" attrs={"data-loop":true, "aria-label":"Featured"}]\n  [@ui.p part="viewport"][#list slides as s][@ui.p part="slide"]${s.title}[/@ui.p][/#list][/@ui.p]\n  [@ui.p part="prev" tag="button" attrs={"aria-label":"Previous slide"}][/@ui.p]\n  [@ui.p part="next" tag="button" attrs={"aria-label":"Next slide"}][/@ui.p]\n  [@ui.p part="dots"][/@ui.p]\n[/@ui.c]',
"code-block": '<pre data-ui-part="code-block"><code id="snippet">${code}</code></pre>\n[@ui.clipboard target="#snippet"]Copy[/@ui.clipboard]',
"collapsible": '[@ui.collapsible trigger="Show 3 more"]\n  <p>ერთი</p><p>ორი</p><p>სამი</p>\n[/@ui.collapsible]',
"datatable": '[@ui.datatable pageSize=10]\n<table>\n  <thead><tr><th data-ui-part="select-all"><input type="checkbox" aria-label="Select all"></th>\n    <th data-sort="title">სათაური</th><th data-sort="views" data-type="number">ნახვები</th></tr></thead>\n  <tbody>[#list articles as a]\n    <tr data-ui-part="row" data-id="${a.id}"><td><input type="checkbox" data-ui-part="row-select"></td><td>${a.title}</td><td>${a.views}</td></tr>\n  [/#list]</tbody>\n</table>\n[/@ui.datatable]',
"dialog": '[@ui.dialog trigger="Edit profile" title="პროფილი" description="შეცვალეთ მონაცემები."]\n  <form method="dialog">\n    <label>სახელი <input name="name" value="${user.name}" autofocus></label>\n    <button value="cancel">Cancel</button><button value="save">Save</button>\n  </form>\n[/@ui.dialog]',
"drawer": '[@ui.dialog kind="sheet" side="right" trigger="ფილტრები" title="ფილტრები"]\n  …filters…\n  [@ui.close]Close[/@ui.close]\n[/@ui.dialog]',
"dropdown-menu": '[@ui.dropdown trigger="მოქმედებები" items=[\n  {"type":"label", "label":"სტატია"},\n  {"label":"რედაქტირება", "shortcut":"⌘E"},\n  {"type":"separator"},\n  {"label":"გამოქვეყნებული", "type":"checkbox", "checked":true},\n  {"label":"გაზიარება", "items":[{"label":"Facebook"}, {"label":"Email"}]},\n  {"label":"წაშლა", "variant":"destructive"}\n]/]',
"context-menu": '[@ui.dropdown kind="context-menu" trigger="Right-click here" items=[\n  {"label":"Back"}, {"label":"Reload"}, {"type":"separator"},\n  {"label":"Show bookmarks", "type":"checkbox"}\n]/]',
"empty": '<div data-ui-part="empty-state">\n  <h3>სტატიები არ არის</h3><p>შექმენით პირველი სტატია.</p>\n  [@ui.button]ახალი სტატია[/@ui.button]\n</div>',
"hover-card": '[@ui.popover kind="hover-card" triggerTag="a" trigger="@levancho"]\n  [@ui.avatar fallback="LD"/] <strong>ლევან დვალიშვილი</strong>\n[/@ui.popover]',
"item": '[@ui.itemGroup label="Notification settings"]\n  [@ui.item title="შეტყობინებები" description="Email and push" media="🔔"]\n    [@ui.switch name="notify" checked=user.notify/]\n  [/@ui.item]\n  [@ui.item title="პროფილი" description="Opens a page" href="/profile"/]\n[/@ui.itemGroup]',
"kbd": 'Press <kbd>Ctrl</kbd> + <kbd>K</kbd>',
"label": '<label for="email">ელ-ფოსტა</label> <input id="email" name="email" type="email">',
"link": '<a href="/articles"[#if current=="articles"] aria-current="page"[/#if]>სტატიები</a>',
"popover": '[@ui.popover trigger="ზომები"]\n  <label>Width <input name="w" value="100%" autofocus></label>\n  [@ui.close]Done[/@ui.close]\n[/@ui.popover]',
"progress": '[@ui.progress value=upload.percent label="Upload"/]\n[@ui.progress label="Loading"/]  [#-- no value = indeterminate --]',
"rating": '[@ui.rating name="stars" value=review.stars!0/]\n[@ui.rating name="avg" value=4 readonly=true/]',
"reparent": '<span data-ui="reparent" data-target="#desktop-slot" data-target-mobile="#mobile-slot"\n      data-media="(max-width: 699px)">…</span>',
"resizable": '[@ui.c ui="resizable"]\n  [@ui.p part="panel" attrs={"data-size":"30", "data-min":"15"}]Sidebar[/@ui.p]\n  [@ui.p part="handle" attrs={"aria-label":"Resize"}][/@ui.p]\n  [@ui.p part="panel" attrs={"data-size":"70"}]Content[/@ui.p]\n[/@ui.c]',
"scroll-area": '[@ui.scrollArea maxHeight="120px" label="Tags"]\n  [#list tags as t]<p>${t}</p>[/#list]\n[/@ui.scrollArea]',
"separator": '[@ui.separator/]\n[@ui.separator vertical=true/]',
"skeleton": '[@ui.skeleton w="220px" h="14px"/]\n[@ui.spinner label="იტვირთება…"/]',
"table": '<table><caption>ბოლო სტატიები</caption>\n  <thead><tr><th scope="col">სათაური</th></tr></thead>\n  <tbody>[#list articles as a]<tr><td>${a.title}</td></tr>[/#list]</tbody>\n</table>',
"theme-switch": '[@ui.themeSwitch key="colibri.theme"]Theme[/@ui.themeSwitch]',
"toast": '[#-- once per layout --]\n[@ui.toaster position="bottom-right" max=3/]\n<script type="module">\n  import { toast } from "@colibri/ui/core/base";\n  toast({ title: "შენახულია", variant: "success", action: { label: "Undo", onClick: undo } });\n</script>',
"toggle": '[@ui.toggle label="Bold" pressed=false]<b>B</b>[/@ui.toggle]',
"tooltip": '[@ui.tooltip text="ეს არის მინიშნება"]\n  <button type="button" data-ui-part="trigger">Hover / focus me</button>\n[/@ui.tooltip]',
"typography": '<h1>${title}</h1><p>${body}</p><blockquote>${quote}</blockquote>',
"message-scroller": '[@ui.c ui="message-scroller"]\n  [@ui.p part="viewport"][#list messages as m]\n    <div data-ui-part="message" data-from="${m.mine?then("me","them")}"><span data-ui-part="bubble">${m.text}</span></div>\n  [/#list][/@ui.p]\n  [@ui.p part="jump" tag="button"]↓ ახალი[/@ui.p]\n[/@ui.c]',
"direction": '<div dir="rtl" lang="ar">\n  [@ui.alert]مرحبا[/@ui.alert]\n</div>',
"attachment": '[@ui.fileInput name="attachments" maxSize="10MB"/]',
"breadcrumb": '[@ui.breadcrumb crumbs=[\n  {"label":"მთავარი", "href":"/"},\n  {"label":"სტატიები", "href":"/articles"},\n  {"label":"რედაქტირება"}\n]/]',
"menu": '[@ui.menubar label="App" menus=[\n  {"label":"ფაილი", "items":[{"label":"ახალი"}, {"label":"გახსნა…"}, {"type":"separator"}, {"label":"ბეჭდვა"}]},\n  {"label":"რედაქტირება", "items":[{"label":"Undo"}, {"label":"Redo"}]}\n]/]',
"navigation-menu": '[@ui.navigationMenu label="Main"]\n  [@ui.navMenu trigger="პროდუქტები"]<a href="/cms">Colibri CMS</a><a href="/ui">Colibri UI</a>[/@ui.navMenu]\n  <li><a href="/contact">კონტაქტი</a></li>\n[/@ui.navigationMenu]',
"pagination": '[@ui.pagination total=pages page=currentPage/]\n[#-- server-side links instead of buttons: --]\n[@ui.pagination total=pages page=currentPage href="?page={page}"/]',
"scrollspy": '[@ui.scrollspy offset=80]\n  [@ui.spyLink href="#intro"]Intro[/@ui.spyLink]\n  [@ui.spyLink href="#usage"]Usage[/@ui.spyLink]\n[/@ui.scrollspy]',
"scrollto": '<a data-ui="scrollto" href="#top" data-offset="64">↑ Back to top</a>',
"sidebar": '[@ui.sidebar id="app-sidebar" key="app.sidebar" label="Main navigation"]\n  …links…\n[/@ui.sidebar]\n[@ui.sidebarToggle target="app-sidebar"]☰[/@ui.sidebarToggle]',
"stepper": '[@ui.stepper linear=true back="უკან" next="შემდეგი" finish="დასრულება" steps=[\n  {"label":"ანგარიში", "content":"<label>ელ-ფოსტა <input type=\'email\' name=\'email\' required></label>"},\n  {"label":"პროფილი", "content":"<label>სახელი <input name=\'name\'></label>"},\n  {"label":"დასრულება", "content":"მზადაა!"}\n]/]',
"sticky": '<header data-ui="sticky" style="position:sticky;top:0">…</header>',
"tabs": '[@ui.tabs default="news" tabs=[{"value":"news","label":"სიახლეები"}, {"value":"sport","label":"სპორტი"}]]\n  [@ui.panel value="news"]სიახლეების პანელი[/@ui.panel]\n  [@ui.panel value="sport"]სპორტის პანელი[/@ui.panel]\n[/@ui.tabs]',
"command": '[@ui.dialog trigger="Command palette" title="Command"]\n  [@ui.command hotkey="k" groups=[\n    {"label":"გვერდები", "options":[{"value":"home","label":"მთავარი","keywords":"main"}, {"value":"articles","label":"სტატიები"}]}\n  ]/]\n[/@ui.dialog]',
"input": '<input name="title" value="${(article.title)!}" placeholder="ტექსტი">',
"input-group": '<div data-ui-part="input-group">\n  <span data-ui-part="addon">https://</span><input name="site" aria-label="Site">\n</div>',
"field": '[@ui.field label="ელ-ფოსტა" id="email" description="არ გავაზიარებთ."\n          error=(errors.email)!""]\n  [@ui.input name="email" id="email" type="email" value=(form.email)! required=true/]\n[/@ui.field]',
"checkbox": '[@ui.checkbox name="remember" checked=form.remember label="დამახსოვრება"/]\n[@ui.checkbox name="all" label="ყველა" controls="#list .row-check"/]',
"radio-group": '[@ui.radioGroup name="lang" value=form.lang label="Language" options=[\n  {"value":"ka", "label":"ქართული"}, {"value":"en", "label":"English"}\n]/]',
"switch": '[@ui.switch name="airplane" checked=settings.airplane label="Airplane mode"/]',
"select": '[@ui.select name="lang" value=form.lang placeholder="აირჩიეთ ენა" groups=[\n  {"label":"ევროპა", "options":[{"value":"ka","label":"ქართული"}, {"value":"en","label":"English"}]}\n]/]\n[@ui.select name="tags" multiple=true placeholder="ტეგები" options=tagOptions/]',
"combobox": '[@ui.combobox name="city" placeholder="ქალაქი…" label="City" options=[\n  {"value":"tbilisi","label":"თბილისი"}, {"value":"batumi","label":"ბათუმი"}\n]/]\n[@ui.combobox name="langs" multiple=true allowCustom=true options=langOptions/]',
"slider": '[@ui.slider name="vol" value=40/]\n[@ui.slider name="price" value="200,800" min=0 max=1000 step=10 labels=["Min","Max"]/]',
"pin-input": '[@ui.pinInput name="otp" length=6/]\n[@ui.pinInput name="pin" length=4 mask=true label="PIN"/]',
"toggle-password": '[@ui.togglePassword name="password" label="Password"/]',
"textarea": '[@ui.textarea name="comment" maxRows=8 maxlength="200" label="Comment"/]',
"file-input": '[@ui.fileInput name="files" maxSize="2MB" drop="ჩააგდეთ ფაილები აქ"/]',
"image-input": '[@ui.imageInput name="avatar" src=(user.avatarUrl)! change="შეცვლა" remove="წაშლა"/]',
"repeater": '[@ui.repeater min=1 max=5 add="+ დამატება"]\n  <input name="items[__i__].name" placeholder="სახელი">\n[/@ui.repeater]',
"color-picker": '[@ui.colorPicker name="brand" value=site.brandColor swatches=["#e11d48", "#16a34a"]/]',
"sortable": '[@ui.sortable name="order" label="Order" items=[\n  {"value":"a","label":"ერთი"}, {"value":"b","label":"ორი"}, {"value":"c","label":"სამი"}\n]/]',
"toggle-group": '[@ui.toggleGroup type="single" value="c" label="Align" items=[\n  {"value":"l","label":"L"}, {"value":"c","label":"C"}, {"value":"r","label":"R"}\n]/]',
"calendar": '[@ui.calendar mode="single" value="2026-10-30"/]\n[@ui.calendar mode="range" months=2/]',
"date-picker": '[@ui.datePicker name="published" value=(article.published?string("yyyy-MM-dd"))! label="Published"/]',
}
FTL.update({
"motion": '<link rel="stylesheet" href="/ui/themes/motion.css">\n<div data-ui-motion="slide-up">…appears with slide-up, exits the same way…</div>\n<div data-ui-motion="fade" data-ui-motion-exit="collapse" data-ui-motion-speed="slow">…</div>\n[#-- register your own (CSS): --]\n<style>\n  @keyframes ui-swing-in { from { opacity:0; transform:rotate(-12deg) } }\n  @keyframes ui-swing-out { to { opacity:0; transform:rotate(10deg) } }\n  [data-ui-motion=swing] { --ui-motion-in:ui-swing-in; --ui-motion-out:ui-swing-out }\n</style>',
"motion-states": '<article data-ui-motion-hover="lift">card</article>\n<input data-ui-motion-focus="ring">\n<span data-ui-motion-loop="spin" aria-hidden="true">⟳</span>\n<div data-ui-motion-loop="shimmer" style="height:14px"></div>',
"motion-play": '<script type="module">\n  import { play } from "@colibri/ui/core/motion";\n  form.addEventListener("submit", (e) => { if (!form.checkValidity()) { e.preventDefault(); play(form, "shake"); } });\n</script>',
"motion-wired": '[#-- default animations come from themes/motion.css; override any part: --]\n[@ui.dropdown trigger="Actions" items=items attrs={}/]\n<div data-ui="dropdown-menu">\n  <button data-ui-part="trigger">Actions</button>\n  <div data-ui-part="content" data-ui-motion="flip">…</div>\n</div>',
"theme-tokens": '<link rel="stylesheet" href="/ui/themes/colibri.css">\n<style>\n  :root {\n    --ui-primary: #0f766e; --ui-primary-foreground: #fff;\n    --ui-radius: 6px; --ui-font: "Noto Sans Georgian", system-ui, sans-serif;\n  }\n  html[data-theme=dark] { --ui-primary: #2dd4bf; --ui-primary-foreground: #042f2e; }\n</style>\n<html data-ui-theme="blue">  [#-- built-in accents: blue green rose orange violet --]',
"theme-scoped": '<section class="admin-dense" style="--ui-control-h:30px; --ui-text-sm:13px; --ui-radius:4px">\n  [@ui.button]Save[/@ui.button]\n</section>',
})

FTL["clothline"] = '[@ui.clothline id="clothline" /]\n[@ui.cell title="Answers" mark="✦" line="#clothline" attrs={"style":"left:16px;top:70px"}]\n  <p>Ask anything.</p>\n[/@ui.cell]\n[@ui.cell title="Projects" mark="◈" hanging=true attrs={"data-persist":"projects"}]…[/@ui.cell]\n[@ui.cell title="Menu" mark="≡" maximize=false attrs={"data-kind":"menu", "data-size":"tiny"}]\n  <a href="/">Home</a><a href="/articles">Articles</a>\n[/@ui.cell]'
